gam1(){return"\u064a\u0628\u0642\u0649 \u0627\u0644\u0645\u0644\u0639\u0628 \u0628\u0627\u0644\u062d\u062c\u0645 \u0646\u0641\u0633\u0647 \u0641\u064a \u0643\u0644 \u062a\u0628\u0648\u064a\u0628\u060c \u0648\u0627\u0644\u0644\u0648\u062d\u0629 \u0627\u0644\u0633\u0641\u0644\u064a\u0629 \u062a\u062a\u0645\u0631\u0631 \u0628\u0634\u0643\u0644 \u0645\u0633\u062a\u0642\u0644. \u0644\u0645\u0633\u0629 \u0648\u0627\u062d\u062f\u0629 \u062a\u0639\u0631\u0636 \u0627\u0644\u0644\u0627\u0639\u0628\u060c \u0648\u0627\u0644\u0636\u063a\u0637 \u0627\u0644\u0645\u0637\u0648\u0644 \u0645\u0639 \u0627\u0644\u0633\u062d\u0628 \u064a\u0646\u0642\u0644\u0647 \u0625\u0644\u0649 \u0645\u0643\u0627\u0646 \u0622\u062e\u0631."},
gam2(){return"\u0627\u0644\u0645\u0633 \u0645\u0631\u0643\u0632\u064b\u0627 \u0634\u0627\u063a\u0631\u064b\u0627 \u0644\u062a\u0638\u0647\u0631 \u0642\u0627\u0626\u0645\u0629 \u0627\u0644\u0645\u0631\u0634\u062d\u064a\u0646 \u0644\u0647 \u0628\u0627\u0644\u062a\u0631\u062a\u064a\u0628: \u0637\u0628\u064a\u0639\u064a \u2190 \u064a\u0635\u0644\u062d \u2190 \u0627\u0636\u0637\u0631\u0627\u0631\u064a. \u0627\u0644\u0644\u0627\u0639\u0628 \u0627\u0644\u0630\u064a \u062a\u062a\u0631\u0643\u0647 \u0641\u064a \u0645\u0646\u0637\u0642\u0629 \u062e\u0627\u0631\u062c \u0627\u0644\u062a\u0634\u0643\u064a\u0644\u0629 \u064a\u063a\u0627\u062f\u0631 \u0627\u0644\u062a\u0634\u0643\u064a\u0644\u0629."},
